function policzPasujace(tablica, predykat) {
  let licznik = 0;
  tablica.forEach(function (element) {
    if (predykat(element)) {
      licznik = licznik + 1;
    }
  });
  return licznik;
}

const jestParzysta = n => n % 2 === 0;
console.log(policzPasujace([1, 2, 3, 4, 5, 6], jestParzysta)); // 3

function stworzOpakowanieLogujace(fn) {
  return function (argument) {
    const wynik = fn(argument);
    return wynik;
  };
}

const pomnozZLogiem = stworzOpakowanieLogujace(n => n * 3);
console.log(pomnozZLogiem(4)); // 12

function wszystkieDodatnie(tablica) {
  let wynik = true;
  tablica.forEach(function (n) {
    if (n <= 0) {
      wynik = false;
    }
  });
  return wynik;
}

console.log(wszystkieDodatnie([1, 2, 3]));  // true
console.log(wszystkieDodatnie([1, -2, 3])); // false

