  { nazwa: "Chleb", dostepny: true },
  { nazwa: "Mleko", dostepny: false },
  { nazwa: "Maslo", dostepny: true }
];

const jestDostepny = p => p.dostepny === true;
const nazwyDostepnych = produkty.filter(jestDostepny).map(p => p.nazwa);

console.log(nazwyDostepnych); // ["Chleb", "Maslo"]

