  return tablicaFunkcji.map(function (fn) {
    return fn(wartosc);
  });
}

console.log(wykonajWszystkie([n => n + 1, n => n * 2, n => n - 3], 10)); // [11, 20, 7]

function polaczPredykaty(predykat1, predykat2) {
  return wartosc => predykat1(wartosc) && predykat2(wartosc);
}

const jestParzysta = n => n % 2 === 0;
const jestDodatnia = n => n > 0;
const jestParzystaIDodatnia = polaczPredykaty(jestParzysta, jestDodatnia);

console.log(jestParzystaIDodatnia(4));  // true
console.log(jestParzystaIDodatnia(-4)); // false
console.log(jestParzystaIDodatnia(3));  // false

function stworzWalidatorZakresu(min, max) {
  return x => x >= min && x <= max;
}

